11	// txChain builds a chain with one block per tx list, hashes h1..hN.
12	func txChain(t *testing.T, txs ...[]string) *Index {
13		t.Helper()
14		index := New()
15		for i, blockTxs := range txs {
16			height := int64(i + 1)
17			parent := "genesis"
18			if height > 1 {
19				parent = fmt.Sprintf("h%d", height-1)
20			}
21			block := Block{Height: height, Hash: fmt.Sprintf("h%d", height), Parent: parent, Txs: blockTxs}
22			if err := index.Append(block); err != nil {
23				t.Fatalf("setup append at height %d: %v", height, err)
24			}
25		}
26		return index
27	}
28	
29	// collectPages follows the cursor chain to the end and returns every page.
30	func collectPages(t *testing.T, index *Index, query TxQuery) []TxPage {
31		t.Helper()
32		var pages []TxPage
33		for {
34			page, err := index.QueryTxs(query)
35			if err != nil {
36				t.Fatalf("query failed: %v", err)
37			}
38			pages = append(pages, page)
39			if page.NextCursor == "" {
40				return pages
41			}
42			query.Cursor = page.NextCursor
43		}
44	}
45	
46	func TestQueryTxsReturnsOrderedOccurrences(t *testing.T) {
47		index := txChain(t,
48			[]string{"t1", "t2", "t1"},
49			[]string{},
50			[]string{"t3", "t1"},
51		)
52		page, err := index.QueryTxs(TxQuery{})
53		if err != nil {
54			t.Fatal(err)
55		}
56		want := []TxHit{
57			{Height: 1, BlockHash: "h1", TxID: "t1", Position: 0},
58			{Height: 1, BlockHash: "h1", TxID: "t2", Position: 1},
59			{Height: 1, BlockHash: "h1", TxID: "t1", Position: 2},
60			{Height: 3, BlockHash: "h3", TxID: "t3", Position: 0},
61			{Height: 3, BlockHash: "h3", TxID: "t1", Position: 1},
62		}
63		if !reflect.DeepEqual(page.Hits, want) {
64			t.Fatalf("hits=%v, want %v", page.Hits, want)
65		}
66		if page.TotalMatches != 5 {
67			t.Fatalf("total=%d, want 5", page.TotalMatches)
68		}
