103	func TestQueryTxsIDSetMatchesAnyAndIgnoresOrder(t *testing.T) {
104		index := txChain(t,
105			[]string{"t1", "t2"},
106			[]string{"t3", "t1"},
107		)
108		page, err := index.QueryTxs(TxQuery{TxIDs: []string{"t1", "t3"}})
109		if err != nil {
110			t.Fatal(err)
111		}
112		want := []TxHit{
113			{Height: 1, BlockHash: "h1", TxID: "t1", Position: 0},
114			{Height: 2, BlockHash: "h2", TxID: "t3", Position: 0},
115			{Height: 2, BlockHash: "h2", TxID: "t1", Position: 1},
116		}
