137	
138	func TestQueryTxsDefaultsAndClamping(t *testing.T) {
139		index := txChain(t,
140			[]string{"a"},
141			[]string{"b"},
142		)
143		// To above the tip is clamped to the tip seen by the first page.
144		page, err := index.QueryTxs(TxQuery{From: 1, To: 100})
