161	func TestQueryTxsRejectsInvalidArguments(t *testing.T) {
162		index := txChain(t, []string{"a"}, []string{"b"})
163		for name, query := range map[string]TxQuery{
164			"negative from":  {From: -1},
165			"negative to":    {To: -2},
166			"to below from":  {From: 3, To: 2},
167			"page too small": {PageSize: -1},
168			"page too large": {PageSize: MaxPageSize + 1},
169		} {
170			if _, err := index.QueryTxs(query); !errors.Is(err, ErrInvalidArgument) {
171				t.Errorf("%s: err=%v, want ErrInvalidArgument", name, err)
172			}
173		}
174		// Boundary page sizes are accepted.
175		for _, size := range []int{0, 1, MaxPageSize} {
176			if _, err := index.QueryTxs(TxQuery{PageSize: size}); err != nil {
177				t.Errorf("page size %d refused: %v", size, err)
178			}
179		}
180	}
181	
182	func TestQueryTxsEmptyRangesSucceed(t *testing.T) {
183		empty := New()
184		page, err := empty.QueryTxs(TxQuery{})
185		if err != nil {
186			t.Fatalf("empty index query failed: %v", err)
187		}
188		if len(page.Hits) != 0 || page.TotalMatches != 0 || page.ToHeight != 0 || page.NextCursor != "" {
189			t.Fatalf("unexpected empty-index page: %+v", page)
190		}
191	
192		index := txChain(t, []string{"a"})
193		page, err = index.QueryTxs(TxQuery{From: 5})
194		if err != nil {
195			t.Fatalf("start above tip failed: %v", err)
196		}
197		if len(page.Hits) != 0 || page.TotalMatches != 0 || page.ToHeight != 1 || page.NextCursor != "" {
198			t.Fatalf("unexpected out-of-range page: %+v", page)
199		}
200	}
201	
202	func TestQueryTxsPaginationCoversRange(t *testing.T) {
203		index := txChain(t,
204			[]string{"a", "b", "c"},
205			[]string{"a", "a"},
206			[]string{},
207			[]string{"b", "c", "a", "a"},
208			[]string{"c"},
209		)
210		full, err := index.QueryTxs(TxQuery{})
211		if err != nil {
212			t.Fatal(err)
213		}
214		if full.TotalMatches != 10 || full.MatchedBlocks != 4 {
215			t.Fatalf("unexpected totals: %+v", full)
216		}
217	
218		var all []TxHit
219		pages := collectPages(t, index, TxQuery{PageSize: 4})
220		if len(pages) != 3 {
221			t.Fatalf("pages=%d, want 3", len(pages))
222		}
223		for i, page := range pages {
224			// Statistics describe the whole range and never change between pages.
225			if page.TotalMatches != 10 || page.MatchedBlocks != 4 || page.ToHeight != 5 {
226				t.Fatalf("page %d stats changed: %+v", i, page)
227			}
228			if i < len(pages)-1 && len(page.Hits) != 4 {
229				t.Fatalf("page %d short: %d hits", i, len(page.Hits))
230			}
231			all = append(all, page.Hits...)
232		}
233		if !reflect.DeepEqual(all, full.Hits) {
234			t.Fatalf("paginated hits differ from single-page hits:\n%v\n%v", all, full.Hits)
235		}
236	}
