238	func TestQueryTxsContinuationPinsTheRange(t *testing.T) {
239		index := txChain(t,
240			[]string{"a"},
241			[]string{"a"},
242			[]string{"a"},
243		)
244		first, err := index.QueryTxs(TxQuery{PageSize: 2})
245		if err != nil {
246			t.Fatal(err)
247		}
248		if first.NextCursor == "" || first.ToHeight != 3 {
249			t.Fatalf("unexpected first page: %+v", first)
250		}
251		// New blocks appended after the first page must not enter this query.
252		for _, height := range []int64{4, 5} {
253			block := Block{Height: height, Hash: fmt.Sprintf("h%d", height), Parent: fmt.Sprintf("h%d", height-1), Txs: []string{"a"}}
254			if err := index.Append(block); err != nil {
255				t.Fatal(err)
256			}
257		}
258		second, err := index.QueryTxs(TxQuery{PageSize: 2, Cursor: first.NextCursor})
259		if err != nil {
260			t.Fatal(err)
261		}
262		want := []TxHit{{Height: 3, BlockHash: "h3", TxID: "a", Position: 0}}
263		if !reflect.DeepEqual(second.Hits, want) {
264			t.Fatalf("hits=%v, want %v", second.Hits, want)
265		}
266		if second.TotalMatches != 3 || second.ToHeight != 3 || second.NextCursor != "" {
267			t.Fatalf("continuation saw new blocks: %+v", second)
268		}
269	}
270	
271	func TestQueryTxsContinuationMayResizePage(t *testing.T) {
272		index := txChain(t,
273			[]string{"a", "b"},
274			[]string{"c"},
275			[]string{"d", "e"},
276		)
277		first, err := index.QueryTxs(TxQuery{PageSize: 1})
278		if err != nil {
279			t.Fatal(err)
280		}
281		rest, err := index.QueryTxs(TxQuery{PageSize: MaxPageSize, Cursor: first.NextCursor})
282		if err != nil {
283			t.Fatal(err)
284		}
285		if len(rest.Hits) != 4 || rest.NextCursor != "" || rest.TotalMatches != 5 {
286			t.Fatalf("unexpected resized page: %+v", rest)
287		}
288	}
289	
290	func TestQueryTxsContinuationAcceptsEquivalentSet(t *testing.T) {
291		index := txChain(t,
292			[]string{"a", "b"},
293			[]string{"a", "b"},
294		)
295		first, err := index.QueryTxs(TxQuery{TxIDs: []string{"a", "b", "b"}, PageSize: 2})
296		if err != nil {
297			t.Fatal(err)
298		}
299		// Same set, reordered and deduplicated: still the same filter.
300		second, err := index.QueryTxs(TxQuery{TxIDs: []string{"b", "a"}, Cursor: first.NextCursor})
301		if err != nil {
302			t.Fatalf("equivalent set refused: %v", err)
303		}
304		if len(second.Hits) != 2 || second.NextCursor != "" {
305			t.Fatalf("unexpected continuation: %+v", second)
306		}
307	}
308	
309	func TestQueryTxsContinuationRejectsChangedConditions(t *testing.T) {
310		index := txChain(t,
311			[]string{"a", "b"},
312			[]string{"a"},
313			[]string{"a"},
314		)
315		first, err := index.QueryTxs(TxQuery{From: 2, TxIDs: []string{"a"}, PageSize: 1})
316		if err != nil {
317			t.Fatal(err)
318		}
319		for name, query := range map[string]TxQuery{
320			"different from":   {From: 1, TxIDs: []string{"a"}, Cursor: first.NextCursor},
321			"to now explicit":  {From: 2, To: 3, TxIDs: []string{"a"}, Cursor: first.NextCursor},
322			"different set":    {From: 2, TxIDs: []string{"b"}, Cursor: first.NextCursor},
323			"wider set":        {From: 2, TxIDs: []string{"a", "b"}, Cursor: first.NextCursor},
324			"filter now empty": {From: 2, Cursor: first.NextCursor},
325		} {
326			if _, err := index.QueryTxs(query); !errors.Is(err, ErrInvalidArgument) {
327				t.Errorf("%s: err=%v, want ErrInvalidArgument", name, err)
328			}
329		}
330		// The valid cursor still works afterwards.
331		if _, err := index.QueryTxs(TxQuery{From: 2, TxIDs: []string{"a"}, Cursor: first.NextCursor}); err != nil {
332			t.Fatalf("valid continuation refused after rejected ones: %v", err)
333		}
334	}
335	
336	func TestQueryTxsCursorSurvivesChangesOutsideRange(t *testing.T) {
337		index := txChain(t,
338			[]string{"a", "a"},
339			[]string{"a"},
340			[]string{"b"},
341			[]string{"b"},
342		)
343		first, err := index.QueryTxs(TxQuery{From: 1, To: 2, PageSize: 1})
344		if err != nil {
345			t.Fatal(err)
346		}
347		if first.TotalMatches != 3 || first.NextCursor == "" {
348			t.Fatalf("unexpected first page: %+v", first)
349		}
350		cursor := first.NextCursor
351	
352		// Duplicate append of the tip: a successful no-op.
353		if err := index.Append(Block{Height: 4, Hash: "h4", Parent: "h3", Txs: []string{"b"}}); err != nil {
354			t.Fatal(err)
355		}
356		// Append beyond the pinned range.
357		if err := index.Append(Block{Height: 5, Hash: "h5", Parent: "h4", Txs: []string{"a"}}); err != nil {
358			t.Fatal(err)
359		}
360		// Reorg confined to heights above the pinned range.
361		if _, err := index.Reorg([]Block{
362			{Height: 4, Hash: "h4b", Parent: "h3", Txs: []string{"x"}},
363			{Height: 5, Hash: "h5b", Parent: "h4b"},
364		}); err != nil {
365			t.Fatal(err)
366		}
367		// Replay of the identical branch, including an in-range block.
368		if _, err := index.Reorg([]Block{
369			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a"}},
370			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"b"}},
371		}); err != nil {
372			t.Fatal(err)
373		}
374	
375		pages := collectPages(t, index, TxQuery{From: 1, To: 2, PageSize: 1, Cursor: cursor})
376		var all []TxHit
377		for _, page := range pages {
378			if page.TotalMatches != 3 || page.ToHeight != 2 {
379				t.Fatalf("continuation stats changed: %+v", page)
380			}
381			all = append(all, page.Hits...)
382		}
383		want := []TxHit{
384			{Height: 1, BlockHash: "h1", TxID: "a", Position: 1},
385			{Height: 2, BlockHash: "h2", TxID: "a", Position: 0},
386		}
387		if !reflect.DeepEqual(all, want) {
388			t.Fatalf("remaining hits=%v, want %v", all, want)
389		}
390	}
391	
392	func TestQueryTxsCursorDiesWithRange(t *testing.T) {
393		build := func(t *testing.T) (*Index, string) {
394			t.Helper()
395			index := txChain(t,
396				[]string{"a"},
397				[]string{"b"},
398				[]string{"c"},
399			)
400			first, err := index.QueryTxs(TxQuery{PageSize: 1})
401			if err != nil {
402				t.Fatal(err)
403			}
404			if first.NextCursor == "" {
405				t.Fatal("expected a continuation cursor")
406			}
407			return index, first.NextCursor
408		}
409	
410		t.Run("block replaced", func(t *testing.T) {
411			index, cursor := build(t)
412			if _, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "h1", Txs: []string{"b"}}}); err != nil {
413				t.Fatal(err)
414			}
415			if _, err := index.QueryTxs(TxQuery{Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
416				t.Fatalf("err=%v, want ErrQueryChanged", err)
417			}
418		})
419	
420		t.Run("same hash different txs", func(t *testing.T) {
421			index, cursor := build(t)
422			// The block keeps its hash but its transaction content changes.
423			if _, err := index.Reorg([]Block{
424				{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"z"}},
425				{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"c"}},
426			}); err != nil {
427				t.Fatal(err)
428			}
429			if _, err := index.QueryTxs(TxQuery{Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
430				t.Fatalf("err=%v, want ErrQueryChanged", err)
431			}
432		})
433	
434		t.Run("chain shortened", func(t *testing.T) {
435			index, cursor := build(t)
436			if _, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "h1"}}); err != nil {
437				t.Fatal(err)
438			}
439			if _, err := index.QueryTxs(TxQuery{Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
440				t.Fatalf("err=%v, want ErrQueryChanged", err)
441			}
442		})
443	
444		t.Run("index stays usable", func(t *testing.T) {
445			index, cursor := build(t)
446			if _, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "h1"}}); err != nil {
447				t.Fatal(err)
448			}
449			if _, err := index.QueryTxs(TxQuery{Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
450				t.Fatalf("err=%v, want ErrQueryChanged", err)
451			}
452			// A fresh first-page query against the new chain state works.
453			page, err := index.QueryTxs(TxQuery{})
454			if err != nil {
455				t.Fatalf("fresh query after reorg failed: %v", err)
456			}
457			if page.ToHeight != 2 || page.TotalMatches != 1 {
458				t.Fatalf("unexpected fresh page: %+v", page)
459			}
460		})
461	}
462	
463	func TestQueryTxsRejectsBadCursors(t *testing.T) {
464		index := txChain(t, []string{"a"}, []string{"b"})
465		first, err := index.QueryTxs(TxQuery{PageSize: 1})
466		if err != nil {
467			t.Fatal(err)
468		}
469		good := first.NextCursor
470		if good == "" {
471			t.Fatal("expected a continuation cursor")
472		}
473	
474		tampered := []byte(good)
475		mid := len(tampered) / 2
476		if tampered[mid] == 'A' {
477			tampered[mid] = 'B'
478		} else {
479			tampered[mid] = 'A'
480		}
481		for name, cursor := range map[string]string{
482			"garbage":   "not-a-cursor",
483			"truncated": good[:len(good)-2],
484			"tampered":  string(tampered),
485		} {
486			if _, err := index.QueryTxs(TxQuery{Cursor: cursor}); !errors.Is(err, ErrInvalidArgument) {
487				t.Errorf("%s: err=%v, want ErrInvalidArgument", name, err)
488			}
489		}
490	
491		// A cursor minted by another index instance is an argument error, even
492		// when the other index holds identical data.
493		other := txChain(t, []string{"a"}, []string{"b"})
494		if _, err := other.QueryTxs(TxQuery{Cursor: good}); !errors.Is(err, ErrInvalidArgument) {
495			t.Fatalf("foreign cursor: err=%v, want ErrInvalidArgument", err)
496		}
497	
498		// None of the failures invalidated the genuine cursor.
499		if _, err := index.QueryTxs(TxQuery{Cursor: good}); err != nil {
500			t.Fatalf("valid cursor refused after rejected ones: %v", err)
501		}
502	}
503	
504	func TestQueryTxsSameCursorSamePage(t *testing.T) {
505		index := txChain(t,
506			[]string{"a"},
507			[]string{"b"},
508			[]string{"c"},
509		)
510		first, err := index.QueryTxs(TxQuery{PageSize: 1})
511		if err != nil {
512			t.Fatal(err)
513		}
514		pageA, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor})
515		if err != nil {
516			t.Fatal(err)
517		}
518		pageB, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: first.NextCursor})
519		if err != nil {
520			t.Fatal(err)
521		}
522		if !reflect.DeepEqual(pageA, pageB) {
523			t.Fatalf("repeated cursor returned different pages:\n%+v\n%+v", pageA, pageB)
524		}
525	}
526	
527	func TestQueryTxsReturnedHitsAreCopies(t *testing.T) {
528		index := txChain(t, []string{"a", "b"})
529		page, err := index.QueryTxs(TxQuery{})
530		if err != nil {
531			t.Fatal(err)
532		}
533		page.Hits[0].TxID = "mutated"
534		page.Hits[0].BlockHash = "mutated"
535		page.Hits[0].Height = 99
536		again, err := index.QueryTxs(TxQuery{})
537		if err != nil {
538			t.Fatal(err)
539		}
540		want := TxHit{Height: 1, BlockHash: "h1", TxID: "a", Position: 0}
541		if again.Hits[0] != want {
542			t.Fatalf("caller mutation leaked into the index: %+v", again.Hits[0])
543		}
544	}
545	
546	func TestQueryTxsDoesNotMutateIndex(t *testing.T) {
547		index := txChain(t,
548			[]string{"a", "b"},
549			[]string{"c"},
550		)
551		blocks, byHash, tip := snapshot(index)
552		for _, page := range collectPages(t, index, TxQuery{PageSize: 1}) {
553			_ = page
554		}
555		requireUnchanged(t, index, blocks, byHash, tip)
556	}
557	
558	func TestQueryTxsConcurrentWithAppends(t *testing.T) {
559		index := chain(t, Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"tx-1"}})
560		stop := make(chan struct{})
561	
562		var writer sync.WaitGroup
563		writer.Add(1)
564		go func() {
565			defer writer.Done()
566			for height := int64(2); height <= 200; height++ {
567				select {
568				case <-stop:
569					return
570				default:
571				}
572				block := Block{
573					Height: height,
574					Hash:   fmt.Sprintf("h%d", height),
575					Parent: fmt.Sprintf("h%d", height-1),
576					Txs:    []string{fmt.Sprintf("tx-%d", height)},
577				}
578				if err := index.Append(block); err != nil {
579					return
580				}
581			}
582		}()
583	
584		var readers sync.WaitGroup
585		for reader := 0; reader < 4; reader++ {
586			readers.Add(1)
587			go func() {
588				defer readers.Done()
589				for round := 0; round < 20; round++ {
590					// Appends above the pinned range never invalidate a query,
591					// so every pagination run must complete and stay consistent.
592					pages := 0
593					seen := 0
594					var total, matched, to int64 = -1, -1, -1
595					query := TxQuery{PageSize: 7}
596					var lastHeight int64
597					var lastPosition = -1
598					for {
599						page, err := index.QueryTxs(query)
600						if err != nil {
601							t.Errorf("query failed during appends: %v", err)
602							return
603						}
604						if total == -1 {
605							total, matched, to = page.TotalMatches, page.MatchedBlocks, page.ToHeight
606						} else if page.TotalMatches != total || page.MatchedBlocks != matched || page.ToHeight != to {
607							t.Errorf("stats changed mid-pagination: %+v", page)
608							return
609						}
610						for _, hit := range page.Hits {
611							if hit.Height < lastHeight || (hit.Height == lastHeight && hit.Position <= lastPosition) {
612								t.Errorf("hits out of order after (%d,%d): %+v", lastHeight, lastPosition, hit)
613								return
614							}
615							if hit.Height > page.ToHeight {
616								t.Errorf("hit above pinned bound: %+v vs %d", hit, page.ToHeight)
617								return
618							}
619							lastHeight, lastPosition = hit.Height, hit.Position
620						}
621						seen += len(page.Hits)
622						pages++
623						if page.NextCursor == "" {
624							break
625						}
626						query.Cursor = page.NextCursor
627					}
628					if int64(seen) != total {
629						t.Errorf("paginated %d hits over %d pages, total says %d", seen, pages, total)
630						return
631					}
632				}
633			}()
634		}
635		readers.Wait()
636		close(stop)
637		writer.Wait()
638	}
